<script setup>
import { reactive } from 'vue'
import { Head, router } from '@inertiajs/vue3'
import AdminLayout from '../../../Layouts/AdminLayout.vue'
import PageHeader from '../../../Components/Ui/PageHeader.vue'
import AccountingNav from '../../../Components/Accounting/AccountingNav.vue'
import AccountingPanel from '../../../Components/Accounting/AccountingPanel.vue'
defineOptions({layout:AdminLayout})
const props=defineProps({currency:Object,accounts:Array,filters:Object,metrics:Object,urls:Object})
const form=reactive({...props.filters})
function visit(){router.get(props.urls.index,{from:form.from||undefined,to:form.to||undefined,show_empty:form.showEmpty?1:0},{preserveState:true,preserveScroll:true})}
function money(v){return `${new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))} ${props.currency.symbol}`}
</script>
<template>
<Head title="ميزان المراجعة"/><PageHeader title="ميزان المراجعة" icon="bi-columns-gap" subtitle="اختبار سريع أن مجموع الأرصدة المدينة يساوي الدائنة"/><AccountingNav :urls="urls" active="trialBalance"/>
<section class="balance-state" :class="metrics.balanced?'ok':'bad'"><span><i class="bi" :class="metrics.balanced?'bi-check2-circle':'bi-exclamation-triangle'"></i></span><div><strong>{{metrics.balanced?'الميزان متوازن':'يوجد فرق يحتاج مراجعة'}}</strong><small>{{metrics.balanced?'يمكن متابعة مراجعة الفترة بثقة.':'افتح دفتر القيود وحدد الحركة غير المتوازنة.'}}</small></div><bdi>{{money(Math.abs(metrics.balanceDebit-metrics.balanceCredit))}}</bdi></section>
<div class="metric-grid"><article><small>حسابات عليها حركة</small><strong>{{metrics.activeAccounts}}</strong><span v-if="metrics.hiddenZero">{{metrics.hiddenZero}} بلا حركة مخفية</span></article><article><small>إجمالي الرصيد المدين</small><strong>{{money(metrics.balanceDebit)}}</strong></article><article><small>إجمالي الرصيد الدائن</small><strong>{{money(metrics.balanceCredit)}}</strong></article></div>
<form class="period-filter" @submit.prevent="visit"><label><span>من</span><input v-model="form.from" type="date" class="form-control"></label><label><span>إلى</span><input v-model="form.to" type="date" class="form-control"></label><label class="switch"><input v-model="form.showEmpty" type="checkbox"><span><strong>إظهار الحسابات بلا حركة</strong><small>للمراجعة الشاملة فقط</small></span></label><button class="btn btn-primary"><i class="bi bi-search"></i> تحديث</button></form>
<AccountingPanel title="أرصدة الحسابات" :description="`${accounts.length} من أصل ${metrics.totalAccounts} حساباً`" icon="bi-columns-gap" compact>
<div class="trial-table"><div class="trial-head"><span>الحساب</span><span>حركة مدينة</span><span>حركة دائنة</span><span>رصيد مدين</span><span>رصيد دائن</span></div><a v-for="account in accounts" :key="account.id" :href="account.ledgerUrl" :class="{muted:account.zero}"><span><bdi>{{account.code}}</bdi><strong>{{account.name}}</strong><small v-if="!account.active">معطّل</small></span><bdi>{{money(account.movementDebit)}}</bdi><bdi>{{money(account.movementCredit)}}</bdi><bdi>{{money(account.balanceDebit)}}</bdi><bdi>{{money(account.balanceCredit)}}</bdi></a><div v-if="!accounts.length" class="empty"><i class="bi bi-inbox"></i><strong>لا توجد حركات في هذه الفترة</strong></div><div class="trial-total"><strong>المجموع</strong><bdi>{{money(metrics.movementDebit)}}</bdi><bdi>{{money(metrics.movementCredit)}}</bdi><bdi>{{money(metrics.balanceDebit)}}</bdi><bdi>{{money(metrics.balanceCredit)}}</bdi></div></div>
</AccountingPanel>
</template>
<style scoped>
