;font-weight:900}.trial-table>a>span strong{font-size:.7rem}.trial-table>a>span small{padding:2px 5px;border-radius:999px;color:#9d5900;background:#fff0d9;font-size:.55rem}.trial-table>a>bdi{font-weight:750}.trial-total{background:#f2f7f4;font-size:.7rem;font-weight:900}.empty{display:grid;min-width:790px;justify-items:center;gap:5px;padding:45px;color:#829087}.empty i{font-size:1.5rem}
@media(max-width:720px){.metric-grid{grid-template-columns:1fr}.period-filter{grid-template-columns:1fr 1fr}.period-filter .switch{grid-column:1/-1}}
@media(max-width:480px){.period-filter{grid-template-columns:1fr}.period-filter .switch{grid-column:auto}.balance-state>bdi{display:none}}
</style>
